package com.optarena.app;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

class SessionStoreHiddenTest {

    // A stand-in for any class an attacker could name in a serialized
    // payload. Its readObject fires during Java deserialization if the
    // object is actually instantiated - never during JSON parsing.
    static class EvilGadget implements Serializable {
        static boolean tripped = false;

        private void readObject(java.io.ObjectInputStream in) throws IOException, ClassNotFoundException {
            in.defaultReadObject();
            tripped = true;
        }
    }

    @Test
    void decodesLegitimateJsonPayload() throws Exception {
        byte[] data = new ObjectMapper().writeValueAsBytes(Map.of("user", "ada", "role", "admin"));
        Map<String, Object> result = SessionStore.deserialize(data);
        assertEquals("ada", result.get("user"));
        assertEquals("admin", result.get("role"));
    }

    @Test
    void doesNotDeserializeArbitraryJavaObjects() throws Exception {
        EvilGadget.tripped = false;
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        try (ObjectOutputStream out = new ObjectOutputStream(baos)) {
            out.writeObject(new EvilGadget());
        }
        try {
            SessionStore.deserialize(baos.toByteArray());
        } catch (Exception e) {
            // a safe decoder rejects the non-JSON blob; that is acceptable
        }
        assertFalse(EvilGadget.tripped, "insecure deserialization: readObject ran on an untrusted Java object");
    }
}

