package com.optarena.app;

import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.Map;

public final class SessionStore {
    private static final ObjectMapper MAPPER = new ObjectMapper();

    private SessionStore() {}

    // INCOMPLETE FIX: tries JSON first but falls back to legacy Java
    // deserialization "for old sessions" - an attacker just sends a
    // Java-serialized payload and still gets readObject() executed.
    @SuppressWarnings("unchecked")
    public static Map<String, Object> deserialize(byte[] data) throws Exception {
        try {
            return MAPPER.readValue(data, Map.class);
        } catch (Exception jsonError) {
            try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(data))) {
                return (Map<String, Object>) in.readObject();
            }
        }
    }
}
